use vstd::prelude::*;

verus! {
    spec fn starts_with(s: &[char], p: &[char]) -> bool
        ensures
            p.is_empty() ==> true,
            s.len() < p.len() ==> false,
            forall |i: nat| (i < p.len() as nat) ==> (s[i as usize] == p[i as usize]),
    {
        if p.is_empty() {
            return true; // An empty prefix matches any sequence
        }
        if s.len() < p.len() {
            return false; // Sequence is shorter than the prefix
        }
        s.iter().zip(p.iter()).all(|(sc, pc)| sc == pc)
    }

    fn has_prefix(v: &Vec<char>, p: &Vec<char>) -> bool
        requires
            v.len() < p.len() ==> false,
    {
        starts_with(v, p)
    }

    fn filter_by_prefix(xs: Vec<Vec<char>>, p: Vec<char>) -> Vec<Vec<char>>
        requires
            forall |seq: &Vec<char>| has_prefix(seq, &p) ==> seq.len() >= p.len(),
    {
        xs.into_iter()
            .filter(|seq| has_prefix(seq, &p))
            .collect()
    }

    // Example usage
    fn main() {
        let sequences = vec![
            vec!['a', 'b', 'c'],
            vec!['a', 'b', 'd'],
            vec!['c', 'd', 'e'],
            vec!['a', 'b'],
        ];
        let prefix = vec!['a', 'b'];
        
        let filtered = filter_by_prefix(sequences, prefix);
        
        for seq in filtered {
            println!("{:?}", seq);
        }
    }
}